//! 🧪️ Native causal clone custody preserves original shared actor leases and complete portable value output.
use super::*;
use semio_framework_value::{FromValue,ToValue,RetainedCloneSource,RetainedCloneGrant,RetainedCloneProgress,RetirementDemand,retained_clone::{RetainedClone,RetainedCloneCursor},retirement::{RetireOwned,controlled::ControlledRetirement}};
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096,"native envelope clone indivisible body {:?}",d);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn observed<T>(run:impl FnOnce()->T)->(T,usize,usize){semio_framework_trace_memory_testing::observe_backing(run)}
fn close<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).ok().unwrap();for turn in 0..32768{if owner.terminal_is_empty(){return}let d=owner.next_demand(4096).unwrap();let(step,a,r)=observed(||owner.step(grant(d)).unwrap());assert_eq!((a,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(turn<32767)}}
#[test]
fn original_causal_envelope_clone_preserves_wire_value_and_shared_actor_identity(){let expected:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for prefix in [0,1,2,7,29,usize::MAX]{let original=MutationEnvelope::from_value(expected.clone().into()).unwrap();let actor=original.actor.0.as_str().as_ptr();type Source=RetainedCloneSource<MutationEnvelope>;let d=RetirementDemand{copy_bytes:Source::constructor_copy_bytes(),capacity_bytes:Source::constructor_capacity_bytes::<()>(),depth:1,..Default::default()};let(mut source,p)=Source::admit_owned(original,(),grant(d)).ok().unwrap();assert!(p.fits(grant(d)));let foreign=MutationEnvelope::from_value(expected.clone().into()).unwrap();let(mut foreign,_)=Source::admit_owned(foreign,(),grant(d)).ok().unwrap();let mut cursor=MutationEnvelope::retained_clone_cursor();let mut steps=0;while !cursor.output_ready()&&steps<prefix{let d=cursor.advance_demands(source.borrow(),4096).unwrap();for axis in 0..5{let value=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if value==0{continue}let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,3=>denied.maximum_release_bytes-=1,_=>denied.maximum_depth-=1};let(step,a,r)=observed(||cursor.advance(source.borrow(),4096,denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!((a,r),(0,0));}let(step,a,r)=observed(||cursor.advance(source.borrow(),4096,grant(d)).unwrap());assert_eq!((a,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));steps+=1;if steps>1{let(error,a,r)=observed(||cursor.advance(foreign.borrow(),4096,grant(d)).unwrap_err());assert_eq!(error.retained_progress(),Default::default());assert_eq!((a,r),(0,0));}assert!(steps<32768);}let output=if prefix==usize::MAX{Some(cursor.take().unwrap())}else{None};if let Some(output)=output.as_ref(){assert_eq!(serde_json::Value::from(output.to_value()),expected);assert_eq!(output.actor.0.as_str().as_ptr(),actor);}cursor.begin_close();for turn in 0..32768{if cursor.terminal_is_empty(){break}let d=cursor.close_demands(4096).unwrap();let(step,a,r)=observed(||cursor.close_step(grant(d)).unwrap());assert_eq!((a,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(turn<32767);}assert!(cursor.terminal_is_empty());if let Some(output)=output{close(output)}for source in [&mut source,&mut foreign]{for turn in 0..32768{if source.terminal_is_empty(){break}let d=source.next_close_demand(4096).unwrap();let(step,a,r)=observed(||source.close_step(grant(d)).unwrap());assert_eq!((a,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(turn<32767);}assert!(source.terminal_is_empty());}}}
